// 스카이젠 - 하늘섬 군도 : behaviour pack script (@minecraft/server 2.0, @minecraft/server-ui 2.0)
// Generated by sky_pack.py: DATA below holds every coordinate of the world (generators, plots, zones...).
import { world, system, ItemStack, ItemLockMode, GameMode, DisplaySlotId, ObjectiveSortOrder, BlockPermutation } from "@minecraft/server";
import { ActionFormData, MessageFormData } from "@minecraft/server-ui";

const DATA = __DATA__;
const SHOPS = __SHOPS__;
const SELL = __SELL__;

const OW = () => world.getDimension("overworld");
const ADMIN_TAG = "sky_admin";
const NIGHT_START = 13000, NIGHT_END = 23000;
const BAN_MSG = (n) => "§c[보안] §f" + n + " 플레이어가 핵을 사용하여 영구밴 됬습니다";
const MENU_ITEM = "minecraft:compass";
const MENU_NAME = "§r§l§b스카이젠 메뉴";
const START_MONEY = 100;

// ------------------------------------------------------------------ small helpers
const key3 = (x, y, z) => x + "," + y + "," + z;
const lower = (v) => String(v).toLowerCase();
function inBox(l, b, m = 0) {
  return l.x >= b[0] + m && l.x < b[3] + 1 - m && l.y >= b[1] && l.y < b[4] + 1 && l.z >= b[2] + m && l.z < b[5] + 1 - m;
}
function blockIn(bx, by, bz, b) {
  return bx >= b[0] && bx <= b[3] && by >= b[1] && by <= b[4] && bz >= b[2] && bz <= b[5];
}
function isAdmin(p) {
  try {
    if (p.hasTag(ADMIN_TAG)) return true;
    const m = lower(p.getGameMode());
    return m === "creative" || m === "spectator";
  } catch (e) { return false; }
}
function getBlock(x, y, z) {
  try { return OW().getBlock({ x, y, z }); } catch (e) { return undefined; }
}
function setBlock(x, y, z, type) {
  const b = getBlock(x, y, z);
  if (!b) return false;
  try { b.setType(type); return true; } catch (e) { return false; }
}
function cmd(c) {
  try { return OW().runCommand(c); } catch (e) { return undefined; }
}
function fmt(n) { return String(Math.floor(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
function tp(p, d, yaw) {
  try {
    p.teleport({ x: d[0] + (Number.isInteger(d[0]) ? 0.5 : 0), y: d[1], z: d[2] + (Number.isInteger(d[2]) ? 0.5 : 0) },
      { dimension: OW(), rotation: { x: 0, y: yaw ?? d[3] ?? 0 } });
  } catch (e) { }
}
function isNight() {
  const t = world.getTimeOfDay();
  return t >= NIGHT_START && t < NIGHT_END;
}
function store(key, def) {
  try {
    const v = world.getDynamicProperty(key);
    return v === undefined ? def : JSON.parse(v);
  } catch (e) { return def; }
}
function save(key, v) {
  try { world.setDynamicProperty(key, JSON.stringify(v)); } catch (e) { }
}
async function showForm(p, form) {
  for (let i = 0; i < 20; i++) {
    const r = await form.show(p);
    if (r.canceled && lower(r.cancelationReason) === "userbusy") {
      await new Promise((res) => system.runTimeout(res, 10));
      continue;
    }
    return r;
  }
  return { canceled: true };
}

// ------------------------------------------------------------------ money
function moneyObj() {
  let o = world.scoreboard.getObjective("money");
  if (!o) o = world.scoreboard.addObjective("money", "§6§l돈 (원)");
  return o;
}
function money(p) {
  try { return moneyObj().getScore(p) ?? 0; } catch (e) { return 0; }
}
function addMoney(p, n) {
  try { moneyObj().setScore(p, Math.max(0, money(p) + n)); } catch (e) { }
}

// ------------------------------------------------------------------ zones
const SAFE = DATA.safe;           // [x1,y1,z1,x2,y2,z2,island]
function safeZoneOf(l) {
  for (const b of SAFE) if (inBox(l, b)) return b[6];
  return undefined;
}
function furnaceRoomOf(l) {
  for (const r of DATA.furnace) if (inBox(l, r.box, 0.0)) return r;
  return undefined;
}

// ------------------------------------------------------------------ plots
let PLOTS = {};            // id -> {owner, ownerId, since}      (loaded in init: no world access at load time)
let BANS = [];             // [{name, id, at, reason}]
let PENDING_RESET = [];    // plot ids waiting for their blocks to be cleared
const PLOT_BY_ID = {};
for (const p of DATA.plots) PLOT_BY_ID[p.id] = p;
function plotAt(bx, by, bz) {
  for (const p of DATA.plots) if (blockIn(bx, by, bz, p.interior)) return p;
  return undefined;
}
function plotOfPlayerPos(l) {
  for (const p of DATA.plots) if (inBox(l, p.zone, 0.3)) return p;
  return undefined;
}
function owns(pl, plot) {
  const o = PLOTS[plot.id];
  return !!o && (o.ownerId === pl.id || o.owner === pl.name);
}
function plotOf(pl) {
  for (const id in PLOTS) {
    const o = PLOTS[id];
    if (o.ownerId === pl.id || o.owner === pl.name) return PLOT_BY_ID[id];
  }
  return undefined;
}

function isPlotButton(bx, by, bz) {
  for (const p of DATA.plots) {
    if ((bx === p.btnOut[0] && by === p.btnOut[1] && bz === p.btnOut[2]) ||
      (bx === p.btnIn[0] && by === p.btnIn[1] && bz === p.btnIn[2])) return true;
  }
  return false;
}
function placeButtons(pl) {
  // the inside button stands in the plot interior: a reset clears it, so it is put back here
  [[pl.btnOut, pl.btnFace[0]], [pl.btnIn, pl.btnFace[1]]].forEach(([q, face]) => {
    const b = getBlock(q[0], q[1], q[2]);
    if (!b || b.typeId === "minecraft:stone_button") return;
    try { b.setPermutation(BlockPermutation.resolve("minecraft:stone_button", { facing_direction: face })); } catch (e) { }
  });
}
function plotEntry(pl) {
  // the owner may have built over the landing spot: climb to the first 2-high gap
  const [x, y, z, yaw] = pl.inside;
  for (let yy = y; yy < pl.interior[4]; yy++) {
    const f = getBlock(x, yy, z), h = getBlock(x, yy + 1, z);
    if (!f || !h) break;
    if (f.isAir && h.isAir) return [x, yy, z, yaw];
  }
  return pl.inside;
}

// ------------------------------------------------------------------ generators
const GENS = {};
for (const g of DATA.gens) GENS[key3(g[0], g[1], g[2])] = g;   // [x,y,z,type,kind,regen]
const pendingGen = new Map();       // key -> tick when it may grow back
function restoreGen(k) {
  const g = GENS[k];
  if (!g) return true;
  const b = getBlock(g[0], g[1], g[2]);
  if (!b) return false;
  try {
    if (b.typeId !== g[3]) b.setType(g[3]);
    return true;
  } catch (e) { return false; }
}
function sweepGens() {
  const now = system.currentTick;
  for (const k in GENS) {
    const due = pendingGen.get(k);
    if (due !== undefined && due > now) continue;
    const g = GENS[k];
    const b = getBlock(g[0], g[1], g[2]);
    if (!b) continue;
    if (b.typeId !== g[3] && (b.typeId === "minecraft:bedrock" || b.typeId === "minecraft:air")) {
      try { b.setType(g[3]); pendingGen.delete(k); } catch (e) { }
    } else if (due !== undefined) pendingGen.delete(k);
  }
}

// ------------------------------------------------------------------ protection
const CONTAINERS = ["chest", "trapped_chest", "barrel", "shulker_box", "hopper", "dropper", "dispenser", "chiseled_bookshelf",
  "flower_pot", "lectern", "decorated_pot", "brewing_stand", "cauldron", "composter", "jukebox", "campfire", "soul_campfire",
  "_bed", "cake", "frame", "noteblock", "beacon", "respawn_anchor", "crafter", "lever", "daylight_detector", "repeater",
  "comparator", "bell", "vault", "trial_spawner", "furnace", "blast_furnace", "smoker", "sign", "end_portal_frame"];
const UTILITY = ["crafting_table", "enchanting_table", "anvil", "grindstone", "smithing_table", "stonecutter_block",
  "loom", "cartography_table", "ender_chest", "_door", "_trapdoor", "fence_gate", "_button"];
const MODIFY_ITEMS = ["bucket", "flint_and_steel", "fire_charge", "bone_meal", "shears", "_hoe", "_shovel", "_axe", "brush",
  "honeycomb", "spawn_egg", "ender_eye", "glass_bottle", "potion", "dye", "ink_sac"];
const BANNED_USE = ["minecraft:ender_pearl", "minecraft:chorus_fruit", "minecraft:wind_charge"];
const lastWarn = new Map();
function warn(p, text) {
  const t = system.currentTick;
  if ((lastWarn.get(p.id) ?? -100) + 30 > t) return;
  lastWarn.set(p.id, t);
  system.run(() => { try { p.onScreenDisplay.setActionBar(text); } catch (e) { } });
}
function inFurnaceUse(bx, by, bz) {
  for (const r of DATA.furnace) for (const f of r.furnaces) if (f[0] === bx && f[1] === by && f[2] === bz) return true;
  return false;
}
function buildAllowed(p, bx, by, bz) {
  const plot = plotAt(bx, by, bz);
  return plot && owns(p, plot);
}

world.beforeEvents.playerBreakBlock.subscribe((ev) => {
  const p = ev.player, b = ev.block;
  if (isAdmin(p)) return;
  const k = key3(b.x, b.y, b.z);
  if (GENS[k]) {
    if (b.typeId === "minecraft:bedrock") ev.cancel = true;
    return;
  }
  if (isPlotButton(b.x, b.y, b.z)) { ev.cancel = true; warn(p, "§c집터 출입 버튼은 부술 수 없어요"); return; }
  if (buildAllowed(p, b.x, b.y, b.z)) return;
  ev.cancel = true;
  const plot = plotAt(b.x, b.y, b.z);
  warn(p, plot ? "§c다른 사람의 집터입니다" : "§c여기서는 블록을 부술 수 없어요 (생성기 · 내 집터만 가능)");
});

world.afterEvents.playerBreakBlock.subscribe((ev) => {
  const b = ev.block;
  const k = key3(b.x, b.y, b.z);
  const g = GENS[k];
  if (!g) return;
  try { b.setType("minecraft:bedrock"); } catch (e) { }
  pendingGen.set(k, system.currentTick + g[5] * 20);
  system.runTimeout(() => { if (restoreGen(k)) pendingGen.delete(k); }, g[5] * 20);
});

world.afterEvents.playerPlaceBlock.subscribe((ev) => {
  const p = ev.player, b = ev.block;
  if (isAdmin(p)) return;
  if (buildAllowed(p, b.x, b.y, b.z)) return;
  let item;
  try { item = b.getItemStack(1); } catch (e) { item = undefined; }
  try { b.setType("minecraft:air"); } catch (e) { }
  if (item) {
    try { p.getComponent("minecraft:inventory").container.addItem(item); } catch (e) { }
  }
  warn(p, "§c블록은 내 집터 안에만 놓을 수 있어요");
});

world.beforeEvents.playerInteractWithBlock.subscribe((ev) => {
  const p = ev.player, b = ev.block;
  const held = ev.itemStack;
  if (held && held.typeId === MENU_ITEM && held.nameTag === MENU_NAME) {
    // menu item used while looking at a block (2.x has no itemUseOn event)
    ev.cancel = true;
    if (ev.isFirstEvent !== false) system.run(() => menuForm(p));
    return;
  }
  if (isAdmin(p)) return;
  const plot = plotAt(b.x, b.y, b.z);
  if (plot) {
    if (!owns(p, plot)) { ev.cancel = true; warn(p, "§c다른 사람의 집터입니다"); }
    return;
  }
  const id = b.typeId.replace("minecraft:", "");
  const item = ev.itemStack ? ev.itemStack.typeId.replace("minecraft:", "") : "";
  if (item && MODIFY_ITEMS.some((s) => item.includes(s))) {
    ev.cancel = true;
    return;
  }
  if (UTILITY.some((s) => id.includes(s))) return;
  if (id.includes("furnace") || id === "smoker") {
    if (inFurnaceUse(b.x, b.y, b.z)) return;
  }
  if (CONTAINERS.some((s) => id.includes(s))) ev.cancel = true;
});

world.beforeEvents.itemUse.subscribe((ev) => {
  const p = ev.source;
  if (!p || isAdmin(p)) return;
  if (BANNED_USE.includes(ev.itemStack.typeId)) {
    ev.cancel = true;
    warn(p, "§c이 서버에서는 사용할 수 없는 아이템입니다");
  }
});

world.beforeEvents.explosion.subscribe((ev) => { ev.cancel = true; });

// ------------------------------------------------------------------ PvP: day / night + safe zones
const lastPvpHit = new Map();
world.beforeEvents.entityHurt.subscribe((ev) => {
  const v = ev.hurtEntity;
  if (!v || v.typeId !== "minecraft:player") return;
  const src = ev.damageSource;
  let att = src && src.damagingEntity;
  if (!att || att.typeId !== "minecraft:player") return;
  if (att.id === v.id) return;
  if (!isNight() || safeZoneOf(v.location) || safeZoneOf(att.location)) {
    ev.cancel = true;
    return;
  }
  lastPvpHit.set(v.id, system.currentTick);
  lastPvpHit.set(att.id, system.currentTick);
});
function inCombat(p) {
  return isNight() && (lastPvpHit.get(p.id) ?? -1000) + 200 > system.currentTick;
}

let nightState = undefined;
function applyTime(announce) {
  const night = isNight();
  if (night === nightState) return;
  nightState = night;
  try {
    world.gameRules.pvp = night;
    world.gameRules.keepInventory = !night;
  } catch (e) {
    cmd("gamerule pvp " + night);
    cmd("gamerule keepinventory " + !night);
  }
  if (!announce) return;
  for (const p of world.getPlayers()) {
    try {
      if (night) {
        p.onScreenDisplay.setTitle("§c§l밤이 되었습니다", { subtitle: "§fPvP 가능 · 죽으면 아이템을 떨어뜨려요", fadeInDuration: 10, stayDuration: 60, fadeOutDuration: 20 });
        p.playSound("mob.wither.spawn", { volume: 0.4 });
      } else {
        p.onScreenDisplay.setTitle("§e§l아침이 밝았습니다", { subtitle: "§fPvP 불가 · 인벤토리 보호", fadeInDuration: 10, stayDuration: 60, fadeOutDuration: 20 });
        p.playSound("random.levelup", { volume: 0.6 });
      }
    } catch (e) { }
  }
  world.sendMessage(night ? "§c[스카이젠] 밤이 되었습니다. 안전구역 밖에서는 PvP가 가능하고, 죽으면 아이템을 잃습니다."
    : "§e[스카이젠] 아침입니다. PvP가 꺼지고 인벤토리가 보호됩니다.");
}

// ------------------------------------------------------------------ bans
function isBanned(p) {
  return BANS.some((b) => b.id === p.id || b.name === p.name);
}
function ban(p, reason) {
  if (isBanned(p)) return;
  BANS.push({ name: p.name, id: p.id, at: Date.now(), reason });
  save("sky:bans", BANS);
  world.sendMessage(BAN_MSG(p.name));
  const r = cmd('kick "' + p.name.replace(/"/g, "") + '" §c핵 사용으로 영구밴 되었습니다');
  if (!r || !r.successCount) {
    // single-player host cannot be kicked: at least throw them out of the plot
    tp(p, DATA.arrivals.hub);
  }
}
const strikes = new Map();
const spawnTick = new Map();
function banCheck() {
  const now = system.currentTick;
  for (const p of world.getPlayers()) {
    if (isAdmin(p)) { strikes.delete(p.id); continue; }
    if ((spawnTick.get(p.id) ?? -1000) + 100 > now) continue;      // grace right after (re)spawning
    const plot = plotOfPlayerPos(p.location);
    if (plot && !owns(p, plot)) {
      const n = (strikes.get(p.id) ?? 0) + 1;
      strikes.set(p.id, n);
      if (n >= 2) ban(p, "plot " + plot.id);
    } else strikes.delete(p.id);
  }
}

// ------------------------------------------------------------------ furnace rooms
const roomOcc = {};       // id -> Set of player ids
function furnaceTick() {
  const players = world.getPlayers();
  for (const r of DATA.furnace) {
    const prev = roomOcc[r.id] ?? new Set();
    const inside = players.filter((p) => inBox(p.location, r.box, 0.0));
    const next = new Set();
    for (const p of inside) {
      if (prev.size > 0 && !prev.has(p.id) && !isAdmin(p)) {
        tp(p, r.out);
        try { p.onScreenDisplay.setActionBar("§c다른 사람이 사용 중인 화로방입니다"); } catch (e) { }
        continue;
      }
      next.add(p.id);
    }
    if ((prev.size > 0) !== (next.size > 0)) {
      setBlock(r.lamp[0], r.lamp[1], r.lamp[2], next.size > 0 ? "minecraft:red_concrete" : "minecraft:lime_concrete");
      if (next.size === 1 && prev.size === 0) {
        for (const p of inside) try { p.onScreenDisplay.setActionBar("§a개인 화로방 " + r.id + " - 혼자 쓰는 중"); } catch (e) { }
      }
    }
    roomOcc[r.id] = next;
  }
}

// ------------------------------------------------------------------ portals
const portalTime = new Map();
const tpCooldown = new Map();
function dest(p, d) {
  if (d === "home") {
    const plot = plotOf(p);
    if (!plot) {
      try { p.onScreenDisplay.setActionBar("§c집터가 없어요 - 주거 섬 집터 사무소에서 살 수 있어요"); } catch (e) { }
      return undefined;
    }
    return plotEntry(plot);
  }
  return DATA.arrivals[d];
}
function portalTick() {
  const now = system.currentTick;
  for (const p of world.getPlayers()) {
    let hit;
    for (const pt of DATA.portals) if (inBox(p.location, pt.box)) { hit = pt; break; }
    if (!hit || (tpCooldown.get(p.id) ?? 0) > now) { portalTime.delete(p.id); continue; }
    if (inCombat(p)) {
      try { p.onScreenDisplay.setActionBar("§c전투 중에는 이동할 수 없어요 (10초)"); } catch (e) { }
      continue;
    }
    const n = (portalTime.get(p.id) ?? 0) + 1;
    portalTime.set(p.id, n);
    const label = hit.kind === "return" ? "§b허브로 귀환" : hit.label;
    if (n < 4) {
      try { p.onScreenDisplay.setActionBar(label + " §7- 잠시 서 계세요 " + "■".repeat(n) + "□".repeat(4 - n)); } catch (e) { }
      continue;
    }
    portalTime.delete(p.id);
    const d = dest(p, hit.dest);
    if (!d) { tpCooldown.set(p.id, now + 60); continue; }
    tp(p, d);
    tpCooldown.set(p.id, now + 60);
    try { p.playSound("mob.endermen.portal", { volume: 0.5 }); } catch (e) { }
  }
}

// ------------------------------------------------------------------ menu item, starter kit
function menuItem() {
  const it = new ItemStack(MENU_ITEM, 1);
  it.nameTag = MENU_NAME;
  it.setLore(["§7우클릭(길게 누르기)으로 메뉴 열기"]);
  try { it.lockMode = ItemLockMode.inventory ?? ItemLockMode.Inventory; } catch (e) { }
  it.keepOnDeath = true;
  return it;
}
function hasMenu(c) {
  for (let i = 0; i < c.size; i++) {
    const it = c.getItem(i);
    if (it && it.typeId === MENU_ITEM && it.nameTag === MENU_NAME) return true;
  }
  return false;
}
function giveMenu(p) {
  try {
    const c = p.getComponent("minecraft:inventory").container;
    if (!hasMenu(c)) {
      if (!c.getItem(8)) c.setItem(8, menuItem());
      else c.addItem(menuItem());
    }
  } catch (e) { }
}
function starterKit(p) {
  if (p.getDynamicProperty("sky:joined")) return;
  p.setDynamicProperty("sky:joined", true);
  addMoney(p, START_MONEY);
  try {
    const c = p.getComponent("minecraft:inventory").container;
    for (const [id, n] of [["minecraft:wooden_pickaxe", 1], ["minecraft:wooden_axe", 1], ["minecraft:wooden_sword", 1], ["minecraft:bread", 8]]) {
      c.addItem(new ItemStack(id, n));
    }
  } catch (e) { }
  system.runTimeout(() => {
    try {
      p.onScreenDisplay.setTitle("§b§l스카이젠", { subtitle: "§f하늘섬 군도에 오신 것을 환영합니다", fadeInDuration: 10, stayDuration: 80, fadeOutDuration: 20 });
      p.sendMessage("§b[스카이젠] §f기본 도구와 " + START_MONEY + "원을 받았어요. 핫바 9번 칸의 §l스카이젠 메뉴§r§f를 우클릭해 보세요.");
      p.sendMessage("§7낮(05~19시)에는 PvP가 꺼지고, 밤에는 안전구역 밖에서 PvP가 가능하며 죽으면 아이템을 떨어뜨립니다.");
    } catch (e) { }
  }, 40);
}

world.afterEvents.playerSpawn.subscribe((ev) => {
  const p = ev.player;
  spawnTick.set(p.id, system.currentTick);
  system.runTimeout(() => {
    // logged in inside a plot that is not (or no longer) theirs: put them outside, this is not a cheat
    const pl = plotOfPlayerPos(p.location);
    if (pl && !owns(p, pl) && !isAdmin(p)) tp(p, pl.outside);
    if (isBanned(p)) {
      p.sendMessage("§c영구밴된 플레이어입니다.");
      cmd('kick "' + p.name.replace(/"/g, "") + '" §c핵 사용으로 영구밴된 플레이어입니다');
      return;
    }
    if (ev.initialSpawn) starterKit(p);
    giveMenu(p);
    if (!isAdmin(p)) { try { p.setGameMode(GameMode.Adventure ?? GameMode.adventure); } catch (e) { } }
  }, 20);
});

// ------------------------------------------------------------------ forms
function shopForm(p, key) {
  if (key === "sell") return sellForm(p);
  const s = SHOPS[key];
  if (!s) return;
  const f = new ActionFormData().title(s.title).body("§f보유 금액: §6" + fmt(money(p)) + "원\n§7누를 때마다 한 묶음씩 구매합니다.");
  for (const it of s.items) f.button("§0" + it.name + " §8x" + it.n + "\n§2" + fmt(it.price) + "원");
  f.button("§c닫기");
  showForm(p, f).then((r) => {
    if (r.canceled || r.selection === undefined || r.selection >= s.items.length) return;
    const it = s.items[r.selection];
    if (money(p) < it.price) {
      p.sendMessage("§c돈이 부족해요. (" + fmt(money(p)) + " / " + fmt(it.price) + "원)");
      return;
    }
    const c = p.getComponent("minecraft:inventory").container;
    if (c.emptySlotsCount < 1) { p.sendMessage("§c인벤토리가 가득 찼어요."); return; }
    addMoney(p, -it.price);
    const left = c.addItem(new ItemStack(it.id, it.n));
    if (left) OW().spawnItem(left, p.location);
    p.playSound("random.orb");
    p.sendMessage("§a구매: " + it.name + " x" + it.n + " (-" + fmt(it.price) + "원)");
    system.runTimeout(() => shopForm(p, key), 4);
  });
}
function sellable(p) {
  const c = p.getComponent("minecraft:inventory").container;
  const tot = {};
  for (let i = 0; i < c.size; i++) {
    const it = c.getItem(i);
    if (!it || !SELL[it.typeId]) continue;
    tot[it.typeId] = (tot[it.typeId] ?? 0) + it.amount;
  }
  return tot;
}
function doSell(p, only) {
  const c = p.getComponent("minecraft:inventory").container;
  let earned = 0, count = 0;
  for (let i = 0; i < c.size; i++) {
    const it = c.getItem(i);
    if (!it || !SELL[it.typeId] || (only && it.typeId !== only)) continue;
    earned += SELL[it.typeId][0] * it.amount;
    count += it.amount;
    c.setItem(i, undefined);
  }
  if (count) {
    addMoney(p, earned);
    p.playSound("random.orb");
    p.sendMessage("§a" + count + "개를 팔아 §6" + fmt(earned) + "원§a을 벌었어요.");
  }
  return earned;
}
function sellForm(p) {
  const tot = sellable(p);
  const ids = Object.keys(tot);
  let all = 0;
  let lines = "";
  for (const id of ids) {
    all += SELL[id][0] * tot[id];
    lines += "§f" + SELL[id][1] + " §7x" + tot[id] + " §8→ §6" + fmt(SELL[id][0] * tot[id]) + "원\n";
  }
  const f = new ActionFormData().title("§l광물 판매소")
    .body("§f보유 금액: §6" + fmt(money(p)) + "원\n\n" + (ids.length ? lines : "§7팔 수 있는 물건이 없어요.\n§7원목 · 돌 · 석탄 · 철 · 금 · 다이아몬드를 가져오세요.\n") +
      "\n§8가격표: " + Object.keys(SELL).filter((k, i, a) => a.findIndex((x) => SELL[x][1] === SELL[k][1]) === i)
        .map((k) => SELL[k][1] + " " + SELL[k][0]).join(" · "));
  const opts = [];
  if (ids.length) { f.button("§2§l모두 팔기\n§r§6" + fmt(all) + "원"); opts.push(null); }
  for (const id of ids) { f.button("§0" + SELL[id][1] + "만 팔기\n§6" + fmt(SELL[id][0] * tot[id]) + "원"); opts.push(id); }
  f.button("§c닫기");
  showForm(p, f).then((r) => {
    if (r.canceled || r.selection === undefined || r.selection >= opts.length) return;
    doSell(p, opts[r.selection]);
    system.runTimeout(() => sellForm(p), 4);
  });
}

