function buyForm(p, pl) {
  if (plotOf(p)) { p.sendMessage("§c이미 집터가 있어요. (1인 1집터)"); return; }
  if (PLOTS[pl.id]) { p.sendMessage("§c이미 팔린 집터입니다."); return; }
  const f = new MessageFormData().title("§l집터 #" + pl.id + " 구매")
    .body("§f가격: §6" + fmt(pl.price) + "원\n§f보유: §6" + fmt(money(p)) + "원\n\n§715x15 크기, 위로 24칸까지 지을 수 있어요.\n§7사고 나면 집터 안으로 이동합니다.")
    .button1("§2§l구매").button2("§l취소");
  showForm(p, f).then((r) => {
    if (r.canceled || r.selection !== 0) return;
    if (plotOf(p) || PLOTS[pl.id]) { p.sendMessage("§c구매할 수 없어요."); return; }
    if (money(p) < pl.price) { p.sendMessage("§c돈이 부족해요. (" + fmt(money(p)) + " / " + fmt(pl.price) + "원)"); return; }
    for (const o of world.getPlayers()) {
      if (o.id !== p.id && inBox(o.location, pl.zone, 0.3)) { p.sendMessage("§c지금은 살 수 없어요."); return; }
    }
    addMoney(p, -pl.price);
    PLOTS[pl.id] = { owner: p.name, ownerId: p.id, since: Date.now() };
    save("sky:plots", PLOTS);
    world.sendMessage("§e[집터] §f" + p.name + "님이 집터 #" + pl.id + "을(를) 샀어요!");
    p.playSound("random.levelup");
    tp(p, plotEntry(pl));
    refreshPlot(pl, true);
  });
}
function abandonForm(p, pl) {
  const f = new MessageFormData().title("§c§l집터 포기")
    .body("§f집터 #" + pl.id + "을(를) 포기할까요?\n§c집터 안의 블록과 상자 속 물건이 모두 지워집니다.\n§f환불: §6" + fmt(Math.floor(pl.price / 2)) + "원")
    .button1("§c§l포기").button2("§l취소");
  showForm(p, f).then((r) => {
    if (r.canceled || r.selection !== 0 || !owns(p, pl)) return;
    for (const o of world.getPlayers()) if (inBox(o.location, pl.zone, 0)) tp(o, pl.outside);
    delete PLOTS[pl.id];
    save("sky:plots", PLOTS);
    addMoney(p, Math.floor(pl.price / 2));
    if (!PENDING_RESET.includes(pl.id)) PENDING_RESET.push(pl.id);
    save("sky:plotreset", PENDING_RESET);
    p.sendMessage("§e집터 #" + pl.id + "을(를) 포기했어요. (+" + fmt(Math.floor(pl.price / 2)) + "원)");
    refreshPlot(pl, true);
  });
}
function resetPlot(pl) {
  const [x1, y1, z1, x2, y2, z2] = pl.interior;
  const f = pl.floor;
  if (!getBlock(x1, f, z1) || !getBlock(x2, f, z2)) return false;
  for (let y = f + 1; y <= y2; y += 12) cmd(`fill ${x1} ${y} ${z1} ${x2} ${Math.min(y + 11, y2)} ${z2} air`);
  cmd(`fill ${x1} ${y1} ${z1} ${x2} ${f - 1} ${z2} dirt`);
  cmd(`fill ${x1} ${f} ${z1} ${x2} ${f} ${z2} grass_block`);
  placeButtons(pl);
  return true;
}
const plotShown = {};      // sign text last written
const mapShown = {};       // board pixel last written (the board and the sign can sit in different chunks)
function refreshPlot(pl, force) {
  const o = PLOTS[pl.id];
  const text = o ? "§l§e집터 #" + pl.id + "\n§r§c주인\n§f" + o.owner : "§l§e집터 #" + pl.id + "\n§r§a판매 중\n§f" + fmt(pl.price) + "원";
  if (force || plotShown[pl.id] !== text) {
    const s = getBlock(pl.sign[0], pl.sign[1], pl.sign[2]);
    if (s) {
      try {
        const sc = s.getComponent("minecraft:sign");
        if (sc) sc.setText(text);
        plotShown[pl.id] = text;
      } catch (e) { }
    }
  }
  const px = o ? "minecraft:red_concrete" : "minecraft:lime_concrete";
  if (pl.map && (force || mapShown[pl.id] !== px) && setBlock(pl.map[0], pl.map[1], pl.map[2], px)) mapShown[pl.id] = px;
}
function plotSweep() {
  for (const pl of DATA.plots) { refreshPlot(pl, false); placeButtons(pl); }
  if (PENDING_RESET.length) {
    const left = PENDING_RESET.filter((id) => !(PLOT_BY_ID[id] && !PLOTS[id] && resetPlot(PLOT_BY_ID[id])));
    if (left.length !== PENDING_RESET.length) { PENDING_RESET = left; save("sky:plotreset", PENDING_RESET); }
  }
}

world.afterEvents.buttonPush.subscribe((ev) => {
  const p = ev.source;
  if (!p || p.typeId !== "minecraft:player") return;
  const b = ev.block;
  for (const pl of DATA.plots) {
    if (b.x === pl.btnOut[0] && b.y === pl.btnOut[1] && b.z === pl.btnOut[2]) {
      const o = PLOTS[pl.id];
      if (!o) { buyForm(p, pl); return; }
      if (owns(p, pl) || isAdmin(p)) { tp(p, plotEntry(pl)); p.playSound("random.door_open"); return; }
      p.onScreenDisplay.setActionBar("§c" + o.owner + "님의 집터입니다 (주인만 들어갈 수 있어요)");
      return;
    }
    if (b.x === pl.btnIn[0] && b.y === pl.btnIn[1] && b.z === pl.btnIn[2]) {
      tp(p, pl.outside);
      p.playSound("random.door_close");
      return;
    }
  }
});

world.beforeEvents.playerInteractWithEntity.subscribe((ev) => {
  const t = ev.target;
  if (!t || t.typeId !== "minecraft:npc") return;
  const tags = t.getTags();
  const tag = tags.find((s) => s.startsWith("sky_"));
  if (!tag) return;
  ev.cancel = true;
  const p = ev.player;
  system.run(() => {
    if (tag === "sky_guide") guideForm(p);
    else if (tag === "sky_plot_clerk") plotClerkForm(p);
    else if (tag.startsWith("sky_shop_")) shopForm(p, tag === "sky_shop_magic2" ? "magic" : tag.slice(9));
  });
});

world.afterEvents.itemUse.subscribe((ev) => {
  const p = ev.source, it = ev.itemStack;
  if (!p || !it || it.typeId !== MENU_ITEM || it.nameTag !== MENU_NAME) return;
  menuForm(p);
});

// ------------------------------------------------------------------ NPCs (summoned when a player is near)
function npcTick(force) {
  const players = world.getPlayers();
  for (const n of DATA.npcs) {
    if (!force && !players.some((p) => Math.hypot(p.location.x - n.x, p.location.z - n.z) < 48)) continue;
    let ents = [];
    try { ents = OW().getEntities({ type: "minecraft:npc", tags: [n.tag], location: { x: n.x, y: n.y, z: n.z }, maxDistance: 8 }); } catch (e) { continue; }
    if (!ents.length) {
      try {
        const e = OW().spawnEntity("minecraft:npc", { x: n.x, y: n.y, z: n.z });
        e.nameTag = n.name;
        e.addTag(n.tag);
        e.addTag("sky_npc");
        e.teleport({ x: n.x, y: n.y, z: n.z }, { facingLocation: { x: n.face[0], y: n.face[1], z: n.face[2] } });
      } catch (e) { }
    } else {
      for (let i = 1; i < ents.length; i++) try { ents[i].remove(); } catch (e) { }
      const e = ents[0], l = e.location;
      if (Math.hypot(l.x - n.x, l.z - n.z) > 0.6 || Math.abs(l.y - n.y) > 1) {
        try { e.teleport({ x: n.x, y: n.y, z: n.z }, { facingLocation: { x: n.face[0], y: n.face[1], z: n.face[2] } }); } catch (e2) { }
      }
    }
  }
}

// ------------------------------------------------------------------ HUD + periodic jobs
function hud() {
  const night = isNight();
  for (const p of world.getPlayers()) {
    if ((portalTime.get(p.id) ?? 0) > 0) continue;
    const z = safeZoneOf(p.location);
    const room = furnaceRoomOf(p.location);
    let where = z ? "§a[안전구역]" : night ? "§c[PvP 구역]" : "§e[PvP 구역 · 낮이라 공격 불가]";
    if (room) where = "§6[개인 화로방 " + room.id + "]" + (night ? " §c밤 PvP" : "");
    try { p.onScreenDisplay.setActionBar(where + " §7| " + (night ? "§c밤" : "§e낮") + " §7| §6" + fmt(money(p)) + "원"); } catch (e) { }
    if (!isAdmin(p) && lower(p.getGameMode()) !== "adventure") {
      try { p.setGameMode(GameMode.Adventure ?? GameMode.adventure); } catch (e) { }
    }
  }
}

let started = false;
function init() {
  if (started) return;
  started = true;
  PLOTS = store("sky:plots", {});
  BANS = store("sky:bans", []);
  PENDING_RESET = store("sky:plotreset", []);
  try {
    const o = moneyObj();
    world.scoreboard.setObjectiveAtDisplaySlot(DisplaySlotId.Sidebar, { objective: o, sortOrder: ObjectiveSortOrder.Descending });
  } catch (e) { }
  try { world.gameRules.doMobSpawning = false; } catch (e) { }
  applyTime(false);
  system.runInterval(() => applyTime(true), 20);
  system.runInterval(banCheck, 10);
  system.runInterval(furnaceTick, 10);
  system.runInterval(portalTick, 5);
  system.runInterval(hud, 20);
  system.runInterval(sweepGens, 100);
  system.runInterval(plotSweep, 100);
  system.runInterval(() => npcTick(false), 40);
  console.warn("[skygen] ready: gens=" + DATA.gens.length + " plots=" + DATA.plots.length + " rooms=" + DATA.furnace.length +
    " safe=" + SAFE.length + " owned=" + Object.keys(PLOTS).length + " bans=" + BANS.length);
}
if (world.afterEvents.worldLoad) world.afterEvents.worldLoad.subscribe(() => init());
system.runTimeout(() => init(), 20);

// ------------------------------------------------------------------ admin / test events
system.afterEvents.scriptEventReceive.subscribe((ev) => {
  const id = ev.id, msg = (ev.message || "").trim();
  if (id === "sky:diag") {
    let gensOk = 0, gensLoaded = 0;
    for (const k in GENS) {
      const g = GENS[k];
      const b = getBlock(g[0], g[1], g[2]);
      if (b) { gensLoaded++; if (b.typeId === g[3]) gensOk++; }
    }
    console.warn("[skygen] diag night=" + isNight() + " pvp=" + world.gameRules.pvp + " keepInventory=" + world.gameRules.keepInventory +
      " gensLoaded=" + gensLoaded + " gensOk=" + gensOk + " plots=" + DATA.plots.length + " owned=" + Object.keys(PLOTS).length +
      " bans=" + BANS.length + " npcs=" + DATA.npcs.length);
  } else if (id === "sky:gentest") {
    // simulate mining the first loaded generator of a kind: break -> bedrock -> regrow
    const kind = msg || "stone";
    for (const k in GENS) {
      const g = GENS[k];
      if (g[4] !== kind) continue;
      const b = getBlock(g[0], g[1], g[2]);
      if (!b) continue;
      b.setType("minecraft:bedrock");
      pendingGen.set(k, system.currentTick + g[5] * 20);
      system.runTimeout(() => { restoreGen(k); pendingGen.delete(k); }, g[5] * 20);
      console.warn("[skygen] gentest " + kind + " at " + k + " -> bedrock, back in " + g[5] + "s");
      return;
    }
    console.warn("[skygen] gentest: no loaded " + kind + " generator");
  } else if (id === "sky:unban") {
    const before = BANS.length;
    BANS = BANS.filter((b) => b.name !== msg);
    save("sky:bans", BANS);
    console.warn("[skygen] unban " + msg + " removed=" + (before - BANS.length));
  } else if (id === "sky:bans") {
    console.warn("[skygen] bans: " + BANS.map((b) => b.name).join(", "));
  } else if (id === "sky:money") {
    const [name, amt] = msg.split(" ");
    const p = world.getPlayers({ name });
    if (p.length) { addMoney(p[0], parseInt(amt) || 0); console.warn("[skygen] money " + name + " " + money(p[0])); }
  } else if (id === "sky:plotfree") {
    const pid = parseInt(msg);
    const pl = PLOT_BY_ID[pid];
    if (pl) for (const o of world.getPlayers()) if (inBox(o.location, pl.zone, 0)) tp(o, pl.outside);
    if (PLOTS[pid]) { delete PLOTS[pid]; save("sky:plots", PLOTS); }
    if (!PENDING_RESET.includes(pid)) { PENDING_RESET.push(pid); save("sky:plotreset", PENDING_RESET); }
    console.warn("[skygen] plot " + pid + " freed");
  } else if (id === "sky:plotgive") {
    const [pid, name] = msg.split(" ");
    PLOTS[parseInt(pid)] = { owner: name, ownerId: "", since: Date.now() };
    save("sky:plots", PLOTS);
    console.warn("[skygen] plot " + pid + " -> " + name);
  } else if (id === "sky:npctest") {
    npcTick(true);
    let n = 0;
    try { n = OW().getEntities({ type: "minecraft:npc", tags: ["sky_npc"] }).length; } catch (e) { }
    console.warn("[skygen] npctest npcs=" + n + "/" + DATA.npcs.length);
  } else if (id === "sky:roomtest") {
    // occupancy logic without players: fake occupants
    const r = DATA.furnace[0];
    roomOcc[r.id] = new Set(["a"]);
    setBlock(r.lamp[0], r.lamp[1], r.lamp[2], "minecraft:red_concrete");
    const b = getBlock(r.lamp[0], r.lamp[1], r.lamp[2]);
    console.warn("[skygen] roomtest lamp=" + (b ? b.typeId : "unloaded"));
    roomOcc[r.id] = new Set();
    setBlock(r.lamp[0], r.lamp[1], r.lamp[2], "minecraft:lime_concrete");
  }
});
